def render_policy(lang: str, kind: str) -> str:
    from nomark.seo import public_head
    policy = POLICIES[lang][kind]
    other = "en" if lang == "id" else "id"
    words = {"id": ("Kembali ke alat", "Diperbarui", "Kontak", "Sistem", "Terang", "Gelap", "Tema"), "en": ("Back to the tool", "Updated", "Contact", "System", "Light", "Dark", "Theme")}[lang]
    back, updated, contact, system, light, dark, theme = words
    sections = "".join(f"<section><h2>{escape(title)}</h2>{''.join(f'<p>{escape(paragraph)}</p>' for paragraph in paragraphs)}</section>" for title, paragraphs in policy["sections"])
    return f'''<!doctype html>
<html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">{public_head(lang, f'/{lang}/{kind}', policy['title'] + ' · NoMark', policy['lead'])}<script src="/static/theme.js"></script><link rel="stylesheet" href="/static/app.css"></head>
<body><div class="page policy-page"><header class="site-header"><a href="/{lang}" class="wordmark" aria-label="NoMark"><img class="brand-logo" src="/static/brand/logo.svg" alt="NoMark" width="124" height="34"><img class="brand-logo-dark" src="/static/brand/logo-dark.svg" alt="" width="124" height="34" aria-hidden="true"></a><nav class="header-actions"><a class="quiet-link" href="/{lang}">{back}</a><select class="policy-theme" data-theme-control aria-label="{theme}"><option value="system">{system}</option><option value="light">{light}</option><option value="dark">{dark}</option></select><a href="/{other}/{kind}" lang="{other}" aria-label="{'English' if other == 'en' else 'Bahasa Indonesia'}">{other.upper()}</a></nav></header>
<main class="policy-main"><h1>{escape(policy['title'])}</h1><p class="policy-date">{updated}: <time datetime="{UPDATED}">{UPDATED}</time></p><p class="policy-lead">{escape(policy['lead'])}</p>{sections}<section><h2>{contact}</h2><p>NoMark · <a href="mailto:{CONTACT}">{CONTACT}</a></p></section></main>
<footer><p>© 2026 NoMark</p><nav class="footer-links"><a href="/{lang}/terms">{POLICIES[lang]['terms']['title']}</a><a href="/{lang}/privacy">{POLICIES[lang]['privacy']['title']}</a><a href="/static/notices.txt">{'Lisensi sumber terbuka' if lang == 'id' else 'Open-source licenses'}</a></nav></footer></div></body></html>'''
